<div x-data="complaintShow({{ $id }})" x-init="init()" x-cloak><div class="mb-7 flex items-end justify-between"><div><p class="text-sm text-slate-600">Informasi laporan masyarakat</p><h2 class="mt-1 text-2xl font-semibold text-navy-900" x-text="item ? code(item) : 'Detail Aduan'">Detail Aduan</h2></div><a href="{{ route('complaints.index') }}" class="action-button">Kembali</a></div><div x-show="error" class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><div x-show="item" class="grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]"><section class="rounded-2xl border border-border bg-white p-6 shadow-sm"><dl class="grid gap-5 sm:grid-cols-2"><div><dt class="detail-label">Jenis aset</dt><dd class="detail-value" x-text="type(item)"></dd></div><div><dt class="detail-label">Status</dt><dd class="detail-value" x-text="item?.status_aduan"></dd></div><div><dt class="detail-label">Kategori</dt><dd class="detail-value" x-text="item?.kategori_aduan || '-' "></dd></div><div><dt class="detail-label">Tanggal</dt><dd class="detail-value" x-text="item?.tanggal_aduan || '-' "></dd></div><div class="sm:col-span-2"><dt class="detail-label">Pelapor</dt><dd class="detail-value" x-text="`${item?.nama_pelapor || '-'} — ${item?.kontak_pelapor || 'Kontak tidak dicantumkan'}`"></dd></div><div class="sm:col-span-2"><dt class="detail-label">Lokasi</dt><dd class="detail-value" x-text="item?.alamat_kejadian || item?.aset?.alamat || '-' "></dd></div><div class="sm:col-span-2"><dt class="detail-label">Deskripsi</dt><dd class="mt-1 whitespace-pre-line text-sm text-slate-700" x-text="item?.deskripsi || '-' "></dd></div></dl><div class="mt-6"><label class="field-label" for="status_aduan">Perbarui status</label><div class="flex gap-2"><select id="status_aduan" x-model="status" class="field-input"><option value="baru">Baru</option><option value="diproses">Diproses</option><option value="selesai">Selesai</option></select><button type="button" @click="update" :disabled="saving" class="action-button-primary">Simpan</button></div></div></section><aside class="rounded-2xl border border-border bg-white p-5 shadow-sm"><div id="complaint-detail-map" class="h-64 overflow-hidden rounded-xl bg-[#dbe7e5]"></div><template x-if="item?.foto"><a :href="photoUrl(item.foto)" target="_blank" rel="noreferrer" class="mt-4 block text-sm font-semibold text-teal-700 underline">Lihat foto pendukung</a></template></aside></div></div>
<script>function complaintShow(id){return{item:null,status:'baru',saving:false,error:'',map:null,marker:null,async init(){try{this.item=(await window.axios.get(`/api/aduan/${id}`)).data;this.status=this.item.status_aduan;this.initMap()}catch(e){this.error=e.response?.data?.message||'Gagal memuat detail aduan.'}},initMap(){this.map=window.Leaflet.map('complaint-detail-map',{center:[-7.6786,109.6565],zoom:11,scrollWheelZoom:false});window.Leaflet.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(this.map);const lat=Number(this.item.latitude||this.item.aset?.latitude),lng=Number(this.item.longitude||this.item.aset?.longitude);if(Number.isFinite(lat)&&Number.isFinite(lng)){this.marker=window.Leaflet.marker([lat,lng],{icon:window.locationMarkerIcon(),title:'Lokasi aduan'}).addTo(this.map);this.marker.bindPopup(`<strong>${this.code(this.item)}</strong><br>${this.type(this.item)}<br>Status: ${this.item.status_aduan}`);this.map.setView([lat,lng],14)}setTimeout(()=>this.map.invalidateSize(),100)},async update(){this.saving=true;try{this.item=(await window.axios.put(`/api/aduan/${id}`,{status_aduan:this.status})).data}catch(e){this.error=e.response?.data?.message||'Gagal memperbarui status.'}finally{this.saving=false}},code(x){return`ADUAN-${String(x.id).padStart(6,'0')}`},type(x){return String(x.aset_type||'').includes('Rambu')?'Rambu':'LPJU'},photoUrl(p){return String(p).startsWith('/')?p:`/storage/${p}`}}}</script>
